<template>
    <li class="nav-item global-search-container">
        <div class="global-search-wrapper">
            <div class="input-group" ref="searchAnchor">
                <input 
                    type="text" 
                    class="form-control global-search-input" 
                    v-model="searchQuery"
                    @input="onSearchInput"
                    @focus="handleSearchFocus"
                    @blur="handleSearchBlur"
                    @keydown.enter="onEnterKey"
                    @keydown.escape="onEscapeKey"
                    @click="handleSearchFocus"
                    @keydown.down.prevent="navigateResults(1)"
                    @keydown.up.prevent="navigateResults(-1)"
                    :placeholder="'Q ' + ($t('Search') || 'Search')"
                    autocomplete="off"
                    ref="searchInput"
                />
                <div class="input-group-append">
                    <span class="input-group-text" @mousedown.prevent.stop @click.prevent.stop="onSearchIconClick">
                        <em class="fa fa-search" v-if="!isSearching"></em>
                        <em class="fa fa-spinner fa-spin" v-if="isSearching"></em>
                    </span>
                </div>
            </div>
            <transition name="fade" @after-enter="onSearchOverlayAfterEnter">
                <div 
                    v-if="showSearchOverlay" 
                    class="global-search-overlay"
                    @click="handleOverlayClick"
                    @mousedown="handleOverlayMouseDown"
                    ref="searchOverlay"
                >
                    <div class="search-overlay-content">
                    <!-- Close Button -->
                    <button type="button" class="search-overlay-close" @click="closeSearchOverlay" title="Close">
                        <em class="fa fa-times"></em>
                    </button>
                    
                    <!-- Module Filter Dropdown -->
                    <div class="search-overlay-header">
                        <div class="search-filters">
                            <select class="filter-dropdown module-dropdown" v-model="selectedModule" @change="onModuleFilterChange">
                                <option value="">All Modules</option>
                                <option v-for="module in availableModules" :key="module.value" :value="module.value">{{ module.text }}</option>
                            </select>

                        </div>
                            </div>

                    <!-- Recent Searches and Suggestions -->
                    <div v-if="searchQuery.length < minSearchLength && !isSearching" class="recent-searches-section">
                         <div class="section-header">
                            <h5>RECENT</h5>
                        </div>
                        <div class="recent-searches-list">
                            <div 
                                v-for="(recent, index) in recentSearches" 
                                :key="'recent-' + index"
                                class="recent-search-item"
                                @mousedown.prevent="selectSuggestion(recent, $event)"
                            >
                                <em class="fa fa-clock-o"></em>
                                <span class="search-text">{{ recent }}</span>
                                <span class="search-label">Recent search</span>
                            </div>
                            </div>
                        </div>


                <!-- Loading State -->
                    <div v-if="isSearching" class="loading-state">
                    <em class="fa fa-spinner fa-spin"></em>
                    <span class="ml-2">{{ $t('Searching') || 'Searching' }}...</span>
                </div>
                
                    <!-- No Results State -->
                    <div v-if="!isSearching && searchQuery.length >= minSearchLength && searchResults.length === 0" class="no-results">
                        <em class="fa fa-info-circle"></em>
                        <span class="ml-2">{{ $t('NoResultsFound') || 'No results found' }}</span>
                    </div>
                
                    <!-- Search Results (when typing) -->
                    <div v-if="searchQuery.length >= minSearchLength && searchResults.length > 0" class="search-results-section">
                        <div class="section-header">
                            <h5>RESULTS</h5>
                        </div>
                        <div class="work-items-list">
                        <div 
                            v-for="(result, index) in displayResults" 
                            :key="result.id || index"
                                class="work-item compact"
                                @click="navigateToItem(result)"
                            > 
                            <div class="work-item-icon">
                                    <em :class="'fa fa-' + (result.icon || result.Icon || getResultIcon(result) || 'circle')" :style="{ color: result.iconColor || '#6c757d' }"></em>
                            </div>
                                <div class="work-item-content">
                                    <div class="work-item-header">
                                        <a
                                            v-if="getResultId(result) && result.url"
                                            :href="result.url"
                                            class="work-item-id-link"
                                             @click="navigateToItem(result)">
                                            <span class="meta-label">{{ getHeaderLabel(result) }}:</span>
                                            <span class="work-item-id-value" v-html="highlightText(getResultId(result), searchQuery)"></span>
                                        </a>
                                        
                                        <span class="work-item-id" v-else-if="getResultId(result)">
                                            <span class="meta-label">{{ getHeaderLabel(result) }}:</span>
                                            <span class="work-item-id-value" v-html="highlightText(getResultId(result), searchQuery)"></span>
                                        </span>
                                        <span class="work-item-title" v-if="getResultDescription(result)">
                                            <span class="meta-label">{{ getDescriptionLabel(result) }}:</span>
                                            <span v-html="highlightText(getResultDescription(result), searchQuery)"></span>
                                        </span>
                                        <span class="work-item-title" v-else v-html="highlightText('', searchQuery)"></span>
                                    </div>
                                    <div class="work-item-meta">
                                        <template v-if="isInvoiceResult(result)">
                                            <span v-if="getParsedField(result, 'bill_issue_date')" class="work-item-meta-item">
                                                <span class="meta-label">{{ $t('BillIssueDate') }}:</span>
                                                <span class="meta-value">{{ formatDate(getParsedField(result, 'bill_issue_date')) }}</span>
                                                </span>
                                            <span v-if="getParsedField(result, 'bill_net_total')" class="work-item-meta-item">
                                                <span class="meta-label">{{ $t('Amount') }}:</span>
                                                 <span class="meta-value">{{ formatCurrency(getParsedField(result, 'bill_net_total')) }}</span> 
                                                 </span>
                                            <span v-if="getParsedField(result, 'billing_division')" class="work-item-meta-item">
                                                <span class="meta-label">{{ $t('divisionname') }}:</span>
                                                 <span class="meta-value">{{ getParsedField(result, 'billing_division') }}</span>
                                            </span>
                                            <span v-if="getParsedField(result, 'project_name')" class="work-item-meta-item">
                                                 <span class="meta-label">{{ $t('Project') }}:</span>
