                                            </span>
                                            <span v-if="getParsedField(result, 'status_name')" class="work-item-meta-item">
                                                <span class="meta-label">{{$t('Status')}}:</span>
                                                <span class="meta-value status-value" :class="getStatusClass(getParsedField(result, 'status_name'))">{{ getParsedField(result, 'status_name') }}</span>
                                            </span>
                                        </template>
                                        <template v-else-if="isAccountResult(result)">
                                            <span v-if="getParsedField(result, 'account_no')" class="work-item-meta-item">
                                                <span class="meta-label">{{ $t('AccountNo') }}:</span>
                                                 <span class="meta-value"><span v-html="highlightText(getParsedField(result, 'account_no'), searchQuery)"></span></span>
                                            </span>
                                             <span v-if="getParsedField(result, 'created_at')" class="work-item-meta-item">
                                                <span class="meta-label">{{ $t('CREATED_AT') }}:</span>
                                                <span class="meta-value status-value" :class="getStatusClass(getParsedField(result, 'created_at'))">{{ formatDate(getParsedField(result, 'created_at')) }}</span>
                                            </span>
                                            <span v-if="getParsedField(result, 'status_name')" class="work-item-meta-item">
                                                <span class="meta-label">{{ $t('Status') }}:</span>
                                                <span class="meta-value status-value" :class="getStatusClass(getParsedField(result, 'status_name'))">{{ getParsedField(result, 'status_name') }}</span>
                                            </span>
                                        </template>
                                        <template v-else-if="isContractResult(result)">
                                            <span v-if="getParsedField(result, 'account_name')" class="work-item-meta-item">
                                                <span class="meta-label">{{ $t('AccountName') }}:</span>
                                                <span class="meta-value"><span v-html="highlightText(getParsedField(result, 'account_name'), searchQuery)"></span></span>
                                            </span>
                                            <span v-if="getParsedField(result, 'user_city')" class="work-item-meta-item">
                                                <span class="meta-label">{{ $t('City') }}:</span>
                                                <span class="meta-value"><span v-html="highlightText(getParsedField(result, 'user_city'), searchQuery)"></span></span> 
                                            </span>
                                            <span v-if="getParsedField(result, 'department_name')" class="work-item-meta-item">
                                                <span class="meta-label">{{ $t('DepartmentName') }}:</span>
                                                 <span class="meta-value"><span v-html="highlightText(getParsedField(result, 'department_name'), searchQuery)"></span></span>
                                            </span>
                                            <span v-if="getParsedField(result, 'account_no')" class="work-item-meta-item">
                                                <span class="meta-label">{{ $t('AccountNo') }}:</span>
                                                 <span class="meta-value"><span v-html="highlightText(getParsedField(result, 'account_no'), searchQuery)"></span></span>
                                            </span>
                                            <span v-if="getParsedField(result, 'status_name')" class="work-item-meta-item">
                                                <span class="meta-label">{{ $t('Status') }}:</span>
                                                <span class="meta-value status-value" :class="getStatusClass(getParsedField(result, 'status_name'))">{{ getParsedField(result, 'status_name') }}</span>
                                            </span>
                                        </template>
                                        <template v-else-if="isCdcCodeResult(result)">
                                            <span v-if="getParsedField(result, 'email_id')" class="work-item-meta-item">
                                                <span class="meta-label">{{ $t('EmailId') }}:</span>
                                                <span class="meta-value" v-html="highlightText(getParsedField(result, 'email_id'), searchQuery)"></span>
                                            </span>
                                            <span v-if="getParsedField(result, 'contract_name')" class="work-item-meta-item">
                                                <span class="meta-label">{{ $t('CONTRACTNAME') }}:</span>
                                                <span class="meta-value" v-html="highlightText(getParsedField(result, 'contract_name'), searchQuery)"></span>
                                            </span>
                                            <span v-if="getParsedField(result, 'sba_name')" class="work-item-meta-item">
                                                <span class="meta-label">{{ $t('Sba') }}:</span>
                                                <span class="meta-value" v-html="highlightText(getParsedField(result, 'sba_name'), searchQuery)"></span>
                                            </span>
                                            <span v-if="getParsedField(result, 'division_name')" class="work-item-meta-item">
                                                <span class="meta-label">{{ $t('divisionname') }}:</span>
                                                <span class="meta-value" v-html="highlightText(getParsedField(result, 'division_name'), searchQuery)"></span>
                                            </span>
                                            <span v-if="getParsedField(result, 'division_description')" class="work-item-meta-item">
                                                <span class="meta-label">{{ $t('DivisionDescription') }}:</span>
                                                <span class="meta-value" v-html="highlightText(getParsedField(result, 'division_description'), searchQuery)"></span>
                                            </span>
                                            <span v-if="getParsedField(result, 'status_name')" class="work-item-meta-item">
                                                <span class="meta-label">{{ $t('Status') }}:</span>
                                                <span class="meta-value status-value" :class="getStatusClass(getParsedField(result, 'status_name'))">{{ getParsedField(result, 'status_name') }}</span>
                                            </span>
                                        </template>
                                        <template v-else-if="isUtilityResult(result)">
                                            <span v-if="getParsedField(result, 'email_id')" class="work-item-meta-item">
                                                <span class="meta-label">{{ $t('EmailId') }}:</span>
                                                <span class="meta-value" v-html="highlightText(getParsedField(result, 'email_id'), searchQuery)"></span>
                                            </span>
                                            <span v-if="getParsedField(result, 'contract_name')" class="work-item-meta-item">
                                                <span class="meta-label">{{ $t('CONTRACTNAME') }}:</span>
                                                <span class="meta-value" v-html="highlightText(getParsedField(result, 'contract_name'), searchQuery)"></span>
                                            </span>
                                            <span v-if="getParsedField(result, 'sba_name')" class="work-item-meta-item">
                                                <span class="meta-label">{{ $t('Sba') }}:</span>
                                                <span class="meta-value" v-html="highlightText(getParsedField(result, 'sba_name'), searchQuery)"></span>
                                            </span>
                                            <span v-if="getParsedField(result, 'division_name')" class="work-item-meta-item">
                                                <span class="meta-label">{{ $t('divisionname') }}:</span>
                                                <span class="meta-value" v-html="highlightText(getParsedField(result, 'division_name'), searchQuery)"></span>
                                            </span>
                                            <span v-if="getParsedField(result, 'division_description')" class="work-item-meta-item">
                                                <span class="meta-label">{{ $t('DivisionDescription') }}:</span>
                                                <span class="meta-value" v-html="highlightText(getParsedField(result, 'division_description'), searchQuery)"></span>
                                            </span>
                                            <span v-if="getParsedField(result, 'status_name')" class="work-item-meta-item">
                                                <span class="meta-label">{{ $t('Status') }}:</span>
                                                <span class="meta-value status-value" :class="getStatusClass(getParsedField(result, 'status_name'))">{{ getParsedField(result, 'status_name') }}</span>
                                            </span>
                                        </template>
                                        <template v-else-if="isTicketResult(result)">
                                            <span v-if="getParsedField(result, 'created_at')" class="work-item-meta-item">
                                                <span class="meta-label">{{ $t('CREATED_AT') }}:</span>
                                                <span class="meta-value" >{{ formatDate(getParsedField(result, 'created_at')) }}</span>
                                            </span>
                                            <span v-if="getParsedField(result, 'priority_id')" class="work-item-meta-item">
                                                <span class="meta-label">{{ $t('Priority') }}:</span>
                                                <span class="meta-value" v-html="highlightText(getParsedField(result, 'priority_id'), searchQuery)"></span>
                                            </span>
                                              <span v-if="getParsedField(result, 'contract_name')" class="work-item-meta-item">
                                                <span class="meta-label">{{ $t('CONTRACTNAME') }}:</span>
                                                <span class="meta-value" v-html="highlightText(getParsedField(result, 'contract_name'), searchQuery)"></span>
                                            </span>
                                            <span v-if="getParsedField(result, 'status_name')" class="work-item-meta-item">
                                                <span class="meta-label">{{ $t('Status') }}:</span>
                                                <span class="meta-value status-value" :class="getStatusClass(getParsedField(result, 'status_name'))">{{ getParsedField(result, 'status_name') }}</span>
                                            </span>
                                        </template>
                                        <template v-else>
                                            <span class="work-item-project">{{ result.type || result.project || 'Result' }}</span>
                                            <span class="work-item-separator" v-if="result.subtitle">•</span>
                                            <span class="work-item-type" v-if="result.subtitle">{{ result.subtitle }}</span>
                                        </template>
                                </div>
                            </div>
                            </div>
                        </div>
                        <!-- View All Results Link -->
                        <div v-if="totalCount > maxResults" class="view-all-results-footer">
                            <a id="viewAllResults" :href="viewAllResultsHref" @click="viewAllResults" class="view-all-link">
                                {{ $t('ViewAllResults') }} ({{ totalCount }}+) <em class="fa fa-arrow-right ml-1"></em>
                            </a>
                    </div>
                    
                    </div>
                    </div>
            </div>
            </transition>

        </div>
    </li>
</template>

<script>
import DataService from "../../services/DataService";

export default {
    name: 'GlobalSearch',
    data() {
        return {
            searchQuery: '',
            searchResults: [],
            isSearching: false,
            minSearchLength: 2,
            maxResults: 10,
            searchDebounceTimer: null,
            searchDebounceDelay: 2000,
            selectedIndex: -1,
            totalCount: 0,
            availableModules: [],
            moduleListData: [],
            selectedModules: [],
            filteredModules: [],
            showSearchOverlay: false,
            recentSearches: [],
            selectedModule: '',
        }
    },
    computed: {
        displayResults() {
            if (this.selectedModules.length > 0) {
                var entityTypes = [];
                this.selectedModules.forEach(m => {
                    var moduleLower = (m || '').toString().toLowerCase().trim();
                    if (moduleLower === 'billing') {
                        entityTypes.push('Talygen_bill');
                        entityTypes.push('TALYGEN_BE_client_configuration');
                    } else if (moduleLower === 'account') {
                        entityTypes.push('Account');
                        entityTypes.push('Talygen_account');
                        entityTypes.push('Talygen_company_account');
                    } else {
                        var mapped = this.getEntityTypeFromModuleName(m);
                        if (mapped) {
                            entityTypes.push(mapped);
                        }
                    }
                });
                entityTypes = entityTypes.map(t => t.toLowerCase());
                return this.searchResults.filter(r => 
                    entityTypes.includes(r.type.toLowerCase())
                );
            }
            return this.searchResults;
        },
        /** Label for account_name meta (Account & Contract search results) */
        accountNameLabel() {
            return this.$t ? this.$t('AccountName') : 'Account Name';
        },
        viewAllResultsHref() {
            var vm = this;
            var queryParams = { q: vm.searchQuery };
            if (vm.selectedModules.length > 0) {
                // Expand Billing to both entity types so the results page also returns both.
                var modulesExpanded = [];
                vm.selectedModules.forEach(m => {
                    var moduleLower = (m || '').toString().toLowerCase().trim();
                    if (moduleLower === 'billing') {
                        modulesExpanded.push('Talygen_bill');
                        modulesExpanded.push('TALYGEN_BE_client_configuration');
                    } else if (moduleLower === 'account') {
                        modulesExpanded.push('Account');
                        modulesExpanded.push('Talygen_account');
                    } else {
                        var mapped = vm.getEntityTypeFromModuleName(m);
                        if (mapped) {
                            modulesExpanded.push(mapped);
                        }
                    }
                });
                queryParams.modules = modulesExpanded.join(',');
            }
            
            if (vm.$router) {
                try {
                    var resolved = vm.$router.resolve({ path: '/Search/Results', query: queryParams });
                    return resolved.href;
                } catch (e) {
                    // Fallback to manual URL building if router resolve fails
                    var queryString = Object.keys(queryParams).map(key => 
                        key + '=' + encodeURIComponent(queryParams[key])
                    ).join('&');
                    return `/Search/Results?${queryString}`;
                }
            } else {
                // Fallback if router not available
                var queryString = Object.keys(queryParams).map(key => 
                    key + '=' + encodeURIComponent(queryParams[key])
                ).join('&');
                return `/Search/Results?${queryString}`;
            }
        }
    },
    created() {
        this.loadAvailableModules();
        this.loadRecentSearches();
        var vm = this;
        vm._searchRepositionRaf = null;
        vm._onSearchLayoutChange = function() {
            if (!vm.showSearchOverlay) {
                return;
            }
            if (vm._searchRepositionRaf != null) {
                return;
            }
            vm._searchRepositionRaf = requestAnimationFrame(function() {
                vm._searchRepositionRaf = null;
                vm.positionOverlay();
            });
        };
    },
    mounted() {
        if (this._onSearchLayoutChange) {
            window.addEventListener('resize', this._onSearchLayoutChange, { passive: true });
            window.addEventListener('scroll', this._onSearchLayoutChange, true);
        }
    },
    methods: {
        onSearchInput(event) {
            var vm = this;
            var query = event.target.value;
            vm.searchQuery = query;

            if (vm.searchDebounceTimer) {
                clearTimeout(vm.searchDebounceTimer);
            }

            vm.selectedIndex = -1;

            var trimmedQuery = query.trim();
            if (trimmedQuery.length < vm.minSearchLength) {
                vm.searchResults = [];
                vm.isSearching = false;
                return;
            }

            vm.searchDebounceTimer = setTimeout(function() {
                if (trimmedQuery.length >= vm.minSearchLength) {
                    vm.isSearching = true;
                    vm.performGlobalSearch(trimmedQuery);
                } else {
                    vm.isSearching = false;
                    vm.searchResults = [];
                }
            }, vm.searchDebounceDelay);
        },
        
        performGlobalSearch(query) {
            var vm = this;
            var trimmedQuery = query ? query.trim() : '';

            if (!trimmedQuery || trimmedQuery.length < vm.minSearchLength) {
                vm.searchResults = [];
                vm.totalCount = 0;
                vm.isSearching = false;
                return;
            }
            
            vm.isSearching = true;

            var modulesParam = '';
            if (vm.selectedModules.length > 0) {
                var modulesExpanded = [];
                vm.selectedModules.forEach(m => {
                    var moduleLower = (m || '').toString().toLowerCase().trim();
                    if (moduleLower === 'billing') {
                        modulesExpanded.push('Talygen_bill');
                        modulesExpanded.push('TALYGEN_BE_client_configuration');
                    } else if (moduleLower === 'account') {
                        modulesExpanded.push('Account');
                        modulesExpanded.push('Talygen_account');
                    } else {
                        var mapped = vm.getEntityTypeFromModuleName(m);
                        if (mapped) {
                            modulesExpanded.push(mapped);
                        }
                    }
                });
                modulesParam = `&modules=${encodeURIComponent(vm.selectedModules.join(','))}&entityType=${encodeURIComponent(modulesExpanded.join(','))}`;
            }
            
            var url = `searchQuery=${encodeURIComponent(trimmedQuery)}&pageNumber=1&pageSize=${vm.maxResults}${modulesParam}`;

            DataService.GlobalSearch(url).then(function(response) {
                vm.isSearching = false;

                if (response && response.data) {
                    var results = [];
                    if (Array.isArray(response.data.results)) {
                        results = response.data.results;
                    } else if (response.data.results && typeof response.data.results === 'object') {
                        console.warn('Results is not an array:', response.data.results);
                    }

                    vm.searchResults = results;

                    var apiTotalCount = response.data.totalCount || 0;
                    vm.totalCount = apiTotalCount > 0 ? apiTotalCount : (results.length > 0 ? results.length : 0);
                    vm.filteredModules = vm.availableModules;

                    if (trimmedQuery && trimmedQuery.length >= vm.minSearchLength) {
                        vm.addToRecentSearches(trimmedQuery);
                    }
                } else {
                    vm.searchResults = [];
                    vm.totalCount = 0;
                }
                vm.schedulePositionOverlay();
            }).catch(function(error) {
                console.error('Global search error:', error);
                vm.isSearching = false;
                vm.searchResults = [];
                vm.totalCount = 0;
                vm.schedulePositionOverlay();
            });
        },
        
        loadRecentSearches() {
            // Load from localStorage
            try {
                var saved = localStorage.getItem('globalSearchRecentSearches');
                if (saved) {
                    this.recentSearches = JSON.parse(saved);
                }
            } catch (e) {
                console.error('Error loading recent searches:', e);
            }
        },
        
        addToRecentSearches(query) {
            // Add to recent searches (max 10)
            if (!this.recentSearches.includes(query)) {
                this.recentSearches.unshift(query);
                if (this.recentSearches.length > 10) {
                    this.recentSearches = this.recentSearches.slice(0, 10);
