            // Reset selected index
            vm.selectedIndex = -1;
            
            // Ensure overlay stays open to show results
            vm.showSearchOverlay = true;
            document.body.style.overflow = 'hidden';
            
            // Trigger search immediately
            if (query.trim().length >= vm.minSearchLength) {
