        onSearchIconClick() {
            var vm = this;
            var query = (vm.searchQuery || '').trim();

            // Cancel pending debounce to avoid duplicate request.
            if (vm.searchDebounceTimer) {
                clearTimeout(vm.searchDebounceTimer);
                vm.searchDebounceTimer = null;
            }

            vm.showSearchOverlay = true;
            document.body.style.overflow = 'hidden';
            vm.schedulePositionOverlay();

            if (query.length >= vm.minSearchLength) {
