            var target = event.target;
            var overlay = this.$refs.searchOverlay;
            
            if (!overlay) {
                return;
            }
            
            // Get the content element
            var content = overlay.querySelector('.search-overlay-content');
            
            // If click is inside the content area, don't close
            if (content && content.contains(target)) {
                return;
            }
            
            // If click is outside content (on backdrop), close the overlay
            // Also re-enable the search input
            this.closeSearchOverlay();
