        navigateResults(direction) {
            var vm = this;
            if (vm.displayResults.length === 0) {
                return;
            }
            
            vm.selectedIndex += direction;
            
            if (vm.selectedIndex < 0) {
                vm.selectedIndex = vm.displayResults.length - 1;
            } else if (vm.selectedIndex >= vm.displayResults.length) {
                vm.selectedIndex = 0;
            }
            
            // Scroll selected item into view
            vm.$nextTick(function() {
                var selectedElement = vm.$refs.resultsContainer;
                if (selectedElement) {
                    var items = selectedElement.querySelectorAll('.search-result-item');
                    if (items[vm.selectedIndex]) {
                        items[vm.selectedIndex].scrollIntoView({ block: 'nearest', behavior: 'smooth' });
                    }
                }
            });
