        viewAllResults(event) {
            var vm = this;

            if (event.ctrlKey || event.metaKey || event.shiftKey || event.button === 1) {
                return;
            }

            event.preventDefault();

            if (vm.$router && vm.$route) {
                var queryParams = { q: vm.searchQuery };

                if (vm.selectedModules.length > 0) {
                    queryParams.modules = vm.selectedModules.join(',');
                }

                var currentRoute = vm.$route;

                var isSameRoute =
                    currentRoute.path === '/Search/Results' &&
                    currentRoute.query.q === queryParams.q &&
                    (currentRoute.query.modules || '') === (queryParams.modules || '');

                if (isSameRoute) {
                    vm.closeSearchOverlay();
                    return;
                }

                vm.$router.push({
                    path: '/Search/Results',
                    query: queryParams
                }).catch(function(err) {
                    if (err.name !== 'NavigationDuplicated') {
                        console.error(err);
                    }
                });
            }

            vm.closeSearchOverlay();
