            if (parsed[fieldName] != null && parsed[fieldName] !== '') {
                return parsed[fieldName];
            }
            /* Alternate casings from search API payloads */
            if (fieldName === 'account_name') {
                if (parsed.AccountName != null && parsed.AccountName !== '') return parsed.AccountName;
                if (parsed.ACCOUNT_NAME != null && parsed.ACCOUNT_NAME !== '') return parsed.ACCOUNT_NAME;
