<script>
// import '../../../Content/Responsive/flags/flag-icon.min.css';
import {
    storeToRefs
} from "pinia";
import $ from "jquery";
const currentAppRootURL = process.env.VUE_APP_CURRENT_SITE_ROOT_URL;
const defaultAppURL = process.env.VUE_APP_DEFAULT_APP_URL;
const fullMenuRedirectionApplied = process.env.VUE_APP_FULL_MENU_APP_REDIRECTION;
const currentUrl = window.location.pathname.substring(1);
import DataService from "../../services/DataService"
import Unreadnotification from "../Notification/Unreadnotification.vue";
import Choosewizards from "../Wizard/choosewizards.vue";
import TimeTracker from "../Tracker/TimeTrackerModal.vue";
import TimerStartOrStop from '../Tracker/TimerStartOrStop.vue';
import FullMenuHeader from "../Model/FullMenuHeader.vue";
import GlobalSearch from "./GlobalSearch.vue";
import authService from "../../services/authservice";
import Bookmarkpopup from "../../components/Model/Addbookmark.vue";
//import TourGuide from "@/components/TourGuide/TourGuide.vue";
import {
    userTimerInfo
} from "../../stores/TimeTracker";
import { useloggedUserInfo } from "../../stores/NavUserInfo";

export default {
    components: {
        Unreadnotification,
        Choosewizards,
        TimeTracker,
        TimerStartOrStop,
        FullMenuHeader,
        GlobalSearch,
        Bookmarkpopup
        ///TourGuide
    },
    data() {
        return {
            instanceType: process.env.VUE_APP_NODE_ENV,
            MenuData: [],
            MenuDataRecord: [],
            MenuDataList: [],
            MaxLoop: 5,
            ModuleName: "",
            MenuDataGroupBy: [],
            MenuCountmodule: 0,
            TotalCount: 0,
            TotalMenuCount: 0,
            Languages: [],
            SelectedLanguage: "en",
            SelectedMenuType: "Top",
            notifications: null,
            showWizard: false,
            showBookmark: false,
            CompanyLogo: null,
            Avatar: null,
            ProfileUrl: null,
            NotificationSettingUrl: null,
            HelpUrl: null,
            UserType: null,
            showTimetrackerModal: false,
            startTimerShow: false,
            timeTrackPage: false,
            //tourGuideShow:false,
            breakOrTimerOnEvent: { "breakTimer": false },
            searchMenu: '',
            IsHeaderShow: false,
            timerPermission: false,
            Permission: false,
            localStorageData: [],
            localStorageLang: '',
            SelectedThemeType: '',
            menutypevalue: '',
            Selectedlangvalue: 'English',
            defaultAppURLVar: defaultAppURL,
            userdata: [],
            screenSize: window.screen.width,
            OpenUnreadnotification: false,
            bookmark: false
        };
    },
    setup() {
        const store2 = userTimerInfo()
        const {
            getTimer
        } = storeToRefs(store2)
        return {
            getTimer,
            store2
        };
    },
    created: async function () {
        window.addEventListener("resize", this.resizeEventMethod);
        var menuSettings = null;
        var localStorage = window.localStorage.TALGYEN_NAVBAR_SETTING;
        if (localStorage == null || typeof (localStorage) == 'undefined') {
            this.SelectedMenuType = (this.GetUserInfo.MenuType == "" ? "Top" : this.GetUserInfo.MenuType);
            this.SelectedThemeType = this.GetUserInfo.Theme;
            this.SelectedLanguage = this.GetUserInfo.lang;
            //this.Selectedlangvalue = this.Selectedlangvalue;

            menuSettings = {
                menuType: (this.GetUserInfo.MenuType == "" ? "Top" : this.GetUserInfo.MenuType),
                lang: this.SelectedLanguage,
                theme: this.GetUserInfo.Theme,
                langname: this.Selectedlangvalue
            }
        } else {
            menuSettings = JSON.parse(localStorage);
            this.SelectedLanguage = menuSettings.lang;
            this.SelectedThemeType = menuSettings.theme;
            //this.Selectedlangvalue = menuSettings.langname;
            this.SelectedMenuType = (menuSettings.menuType == "" ? "Top" : menuSettings.menuType);
        }
        if(this.SelectedMenuType && this.SelectedMenuType.trim() == ""){
            this.SelectedMenuType = "Top";
        }
        console.log("menuSettings", menuSettings);
        console.log("this.GetUserInfo", this.GetUserInfo);
        window.localStorage.setItem('TALGYEN_NAVBAR_SETTING', JSON.stringify(menuSettings));
        this.resizeEventMethod();
        // if(this.screenSize > 991){
        //     if (this.SelectedMenuType == 'Left') {
        //         $("body").addClass("menu-left-wrapper");
        //         $('li').removeClass("fixed-top");
        //         $('ul').removeClass("show");
        //     }
        //     else {
        //         $("body").removeClass("menu-left-wrapper").removeClass("wrapper-shrink");
        //         $('li.navbar').addClass("fixed-top");
        //         $('ul').removeClass("show");
        //     }
        // } else {
        //     this.SelectedMenuType = "Top";
        // }

        // this.localStorageLang = window.localStorage.languageSet;
        window.onbeforeunload = this.closeComponent;
        this.CompanyLogo = this.GetUserInfo.CompanyLogo;
        this.UserType = this.GetUserInfo.UserType;
        this.Avatar = this.GetUserInfo.Avatar;
        this.Gender = this.GetUserInfo.Gender;
        console.log("av", this.Avatar);
        if (!this.CompanyLogo || this.CompanyLogo.toLowerCase() == "company-logo.jpg") {
            this.CompanyLogo = '/Content/images/DefaultImages/company-logo.jpg';
        } else {
            await this.GetCompanyLogo(this.CompanyLogo);
        }

        //this.ProfileUrl = defaultAppURL + '/MyProfile/Index?companyid=' + this.GetUserInfo.CompanyId;
        this.ProfileUrl = currentAppRootURL + '/MyProfile/Index';
        //this.NotificationSettingUrl=defaultAppURL + '/Notification/Index';
        this.NotificationSettingUrl = currentAppRootURL + '/Notification/Index';
        this.HelpUrl = currentAppRootURL + '/Help/HelpAndGuide';
        this.GetFULLMenuData();
        this.GetLanguageList(this.GetUserInfo);
        await this.store2.getTimerInfo();
        this.IsHasPermission('Timer', 'index', 'timer');
        setTimeout(() => {
            this.GetTourGuidePermission();
        }, 2000);
        if (!(this.Avatar == null || this.Avatar == " " || this.Avatar == "" || this.Avatar == undefined)) {
            await this.GetUserImage(this.Avatar)
        }
        else {
            if (this.Gender == "M") {
                this.Avatar = '/Content/images/DefaultImages/avatar-icon.jpg'
            } else {
                this.Avatar = '/Content/images/DefaultImages/avatar-icon-girl.jpg'
                // this.Avatar =  '/Content/images/DefaultImages/avatar-icon.jpg'
            }
        }
        //---------------hide help/support link from footer------------------
        if (this.GetUserInfo.CompanyId == 125549 || this.GetUserInfo.CompanyId == 125643) {
            let helplink = document.getElementById("FooterHelpLink");
            helplink.classList.add("d-none");
            let supportTicket = document.getElementById("FooterTicketSupportLink");
            supportTicket.classList.add("d-none");
        }
        //-------------------------------------------------------------------------
    },
    watch: {
        '$route.path': {
            handler: async function (search) {
                this.timeTrackPage = false
                let url = `/Timer/Index`
                //console.log("check",search.toLowerCase(),url.toLowerCase())
                if (search.toLowerCase().localeCompare(url.toLowerCase()) != 0) {
                    this.GetTimer();
                    this.timeTrackPage = false
                } else {
                    // console.log("second",search)
                    this.timeTrackPage = true
                }
                if (this.$route.query.reload == 'reload') {
                    this.timeTrackPage = true
                    const query = Object.assign({}, this.$route.query);
                    delete query.reload;
                    await this.store2.getTimerInfo();
                    this.$router.push({ query: query })
                    this.timeTrackPage = false
                }
            },
            deep: true,
            immediate: true
        }
    },
    methods: {
        getLanguageIcon: function () {
            try {
                var ths = this;
                var getSelectedLang = this.Languages.filter((x) => { return (x.LANGCODE || 'en').toLowerCase() == (ths.SelectedLanguage || 'en').toLowerCase() });
                if (getSelectedLang.length > 0) {
                    return getSelectedLang[0].LANG_ICON;
                } else {
                    return "";
                }
            } catch (exc) {
                return "";
            }
        },
        resizeEventMethod: function () {
            var localStorage = window.localStorage.TALGYEN_NAVBAR_SETTING;
            if (localStorage == null || typeof (localStorage) == 'undefined') {
                this.SelectedMenuType = (this.GetUserInfo.MenuType == "" ? "Top" : this.GetUserInfo.MenuType);
            } else {
                let menuSettings = JSON.parse(localStorage);
                this.SelectedMenuType = (menuSettings.menuType == "" ? "Top" : menuSettings.menuType);
            }
            if(this.SelectedMenuType && this.SelectedMenuType.trim() == ""){
                this.SelectedMenuType = "Top";
            }
            
            this.screenSize = window.screen.width;
            if (this.screenSize > 991) {
                this.$nextTick(() => {
                    if (this.SelectedMenuType == 'Left') {
                        $("body").addClass("menu-left-wrapper");
                        $('li').removeClass("fixed-top");
                        $('ul').removeClass("show");
                    }
                    else {
