<template>

    <div class="my-popups">
        <loader :is-visible="isLoading"></loader>
        <div class="modal d-block">
            <div class="modal-dialog modal-dialog-centered">
                <div class="modal-content">
                    <div class="modal-header">
                        <h5 class="modal-title">
                            {{ $t('MessageDetails') }}
                        </h5>
                        <button v-on:click="closePopup()" href="javascript:;" class="close"><em class="fa fa-times"
                                aria-hidden="true"></em></button>
                    </div>
                    <div id="popDetails" class="modal-body lineheightnormal" v-if="itemDetail">
                        <div class="row">
                            <div class="col-md-6 col-lg-4">
                                <div class="form-group">
                                    <label>
                                        <b>Subject:</b>
                                        <span
                                            v-if='itemDetail.Type == "LOCATION_LOW_INVENTORY_ALERT" || itemDetail.Type == "MIN_STOCK_ALERT" || itemDetail.Type == "JOB_APPLY" || itemDetail.Type == "INTERVIEW_ACCEPTED" || itemDetail.Type == "INTERVIEW_REJECTED" || itemDetail.Type == "INTERVIEW_RESCHEDULE_REQUESTED"'>
                                            {{ itemDetail.Title }}
                                        </span>
                                        <span style="text-wrap: wrap;" v-else>
                                            {{ itemDetail.Title + " By" + " " + itemDetail.PostedBy }}
                                        </span>
                                    </label>
                                </div>
                            </div>
                            <div class="col-md-6 col-lg-4">
                                <div class="form-group">
                                    <label>
                                        <b>Posted By:</b>
                                        <span
                                            v-if='UserType != "CL" && itemDetail.Type != "ASSET_OVERDUE_ASSIGNER" && itemDetail.Type != "ASSET_OVERDUE_USER"'>
                                            <span
                                                v-if='itemDetail.Type == "LOCATION_LOW_INVENTORY_ALERT" || itemDetail.Type == "MIN_STOCK_ALERT" || itemDetail.Type == "JOB_APPLY" || itemDetail.Type == "INTERVIEW_ACCEPTED" || itemDetail.Type == "INTERVIEW_REJECTED" || itemDetail.Type == "INTERVIEW_RESCHEDULE_REQUESTED"'>
                                                {{ $t('AutoAlertBySystem') }}
                                            </span>
                                            <span v-else>
                                                {{ itemDetail.PostedBy }}
                                            </span>
                                        </span>
                                    </label>
                                </div>
                            </div>
                            <template v-if='itemDetail.Type == "CRM"'>
                                <div class="col-md-6 col-lg-4" v-if='itemDetail.RepliedTo != null'>
                                    <div class="form-group">
                                        <label><b>{{ $t('LeadOwner') }}:</b> {{ itemDetail.RepliedTo }}</label>
                                    </div>
                                </div>
                                <div class="col-md-6 col-lg-4" v-else-if="itemDetail.AssignFrom != null">
                                    <div class="form-group">
                                        <label><b>{{ $t('ContactPerson') }}:</b> {{ itemDetail.AssignFrom }}</label>
                                    </div>
                                </div>
                            </template>
                            <div class="col-md-6 col-lg-4">
                                <div class="form-group">
                                    <label>
                                        <b>Date And Time:</b> {{ $options.filters.formatDate(itemDetail.PostedDate) }}
                                        at {{
                                            formatTimeIn12Hour(itemDetail.PostedDate)
                                        }}
                                    </label>
                                </div>
                            </div>
                            <div class="col-lg-12">
                                <div class="form-group">
                                    <label
                                        v-if='itemDetail.Type == "FILE_ADDED" || itemDetail.Type == "FILE_UPDATED" || itemDetail.Type == "FILE_DELETED"'>
                                        <b>Message:</b>
                                        <span>{{ itemDetail.Message }} {{ $t('And') }} {{ $t('Visable') }} {{ $t('To') }}
                                            {{ itemDetail.RepliedTo }}</span>
                                    </label>
                                    <label v-else><b>Message:</b> <span v-html="itemDetail.Message"></span></label>
                                </div>
                            </div>
                            <div class="col-12 text-right mt-1">
                                <span>                           
                                    <template v-if="itemDetail.ReferenceId > 0">
                                        <a v-if="itemDetail.Type === 'QUOTATION_CREATED' || itemDetail.Type === 'QUOTATION_ACCEPTED' || itemDetail.Type === 'QUOTATION_REJECTED' || itemDetail.Type === 'QUOTATION_SENT' || itemDetail.Type === 'QUOTATION_COMMENT'"
                                            class="btn btn-info formbtn inline-block" :title="$t('viewDetail')" :href="getQuotationUrl">{{ $t('viewDetail') }}
                                        </a>
                                        <a v-if="itemDetail.Type === 'NEW_ASSET_REQUISITION_COMMENT'"
                                            class="btn btn-info formbtn inline-block"
                                            :title="viewDetail"
                                            :href="getAssetRequisitionCommentUrl">
                                            {{ $t('viewDetail') }}
                                        </a>

                                        <a v-if="itemDetail.Type === 'NEW_ASSET_REQUISITION'"
                                            class="btn btn-info formbtn inline-block"
                                         :title="$t('viewDetail')"
                                            :href="getNewAssetRequisitionUrl">
                                            {{ $t('viewDetail') }}
                                        </a>

                                        <a v-if="itemDetail.Type === 'ASSET_REQUISITION'"
                                            class="btn btn-info formbtn inline-block"
                                           :title="$t('viewDetail')"
                                            :href="getAssetRequisitionUrl">
                                            {{ $t('viewDetail') }}
                                        </a>

                                        <a v-if="itemDetail.Type === 'FEEDBACK_C_FROM'"
                                            class="btn btn-info formbtn inline-block"
                                         :title="$t('viewDetail')"
                                            :href="getFeedbackUrl">
                                            {{ $t('viewDetail') }}
                                        </a>

                                        <a v-if="itemDetail.Type === 'MessageBoard' || itemDetail.Type === 'MessageComment'"
                                            class="btn btn-info formbtn inline-block"
                                         :title="$t('viewDetail')"
                                            :href="getProjectOverviewUrl">
                                            {{ $t('viewDetail') }}
                                        </a>

                                        <a v-if="itemDetail.Type === 'NewMessage' || itemDetail.Type === 'Comment'"
                                            class="btn btn-info formbtn inline-block"
                                         :title="$t('viewDetail')"
                                            :href="getProjectOverviewOrRequestTimeUrl">
                                            {{ $t('viewDetail') }}
                                        </a>
                                        <a v-if="['CLAIM_CREATED', 'CLAIM_APPROVE', 'CLAIM_REJECT', 'TICKET_CC_OPTION', 'TICKET_CREATED', 'TICKET_ASSIGN', 'TICKET_REPLY', 'TICKET_TRANSFER', 'TICKET_STATUS_CHANGE', 'TICKET_SPLIT', 'TICKET_MERGE', 'TICKET_SLA_VIOLATION_TIME_REMINDER_RESOLVE_DUE', 'TICKET_SLA_VIOLATION_TIME_REMINDER_RESPONSE_DUE', 'TICKET_SLA_BEFORE_RESOLVE', 'TICKET_SLA_BEFORE_RESPONSE'].includes(itemDetail.Type)" 
                                           class="btn btn-info formbtn inline-block" :title="$t('ViewDetail')" :href="getTicketingDetailUrl">{{ $t('ViewDetail') }}
                                        </a>
                                    </template>
                                    <template v-else>
                                        <a v-if="itemDetail.Type === 'ENTRY_FLAGGED' || itemDetail.Type === 'ENTRY_UNFLAGGED' || itemDetail.Type === 'ENTRY_COMMENTED'"
                                        class="btn btn-info formbtn inline-block"
                                       :title="$t('viewDetail')"
                                        :href="getTrackEntryFlagUrl">
                                        {{ $t('viewDetail') }}
                                        </a>

                                        <a v-if="itemDetail.Type === 'TOTAL_FLAGGED_RECORDS'"
                                        class="btn btn-info formbtn inline-block"
                                        :title="$t('viewDetail')"
                                        :href="getClientInvoiceUrl">
                                        {{ $t('viewDetail') }}
                                        </a>

                                        <a v-if="itemDetail.Type === 'LOCATION_LOW_INVENTORY_ALERT'"
                                        class="btn btn-info formbtn inline-block"
                                       :title="$t('viewDetail')"
                                        :href="getAssetCatalogUrl">
                                        {{ $t('viewDetail') }}
                                        </a>

                                        <a v-if="itemDetail.Type === 'MIN_STOCK_ALERT'"
                                        class="btn btn-info formbtn inline-block"
                                        :title="$t('viewDetail')"
                                        :href="getMyItemsUrl">
                                        {{ $t('viewDetail') }}
                                        </a>

                                        <a v-if="itemDetail.Type === 'EXP_APPR_COMMENT'"
                                        class="btn btn-info formbtn inline-block"
                                        :title="$t('viewDetail')"
                                        :href="getExpensesUrl">
                                        {{ $t('viewDetail') }}
                                        </a>
                                    </template>
                                </span>
                            </div>
                        </div>
                    </div>

                </div>
            </div>
        </div>
    </div>

</template>
<script>
import DataService from '../../services/DataService'
export default {
    props: {
        id: null,
        type: null
    },
    data: function () {
        return {
            isLoading: false,
            itemDetail: null,
            UserType: null,
            Currency:null,
            CompanyId:null
        }
    },
    created: function () {
        var vm =this;
        vm.UserType = vm.GetUserInfo.UserType;
        vm.CompanyId = vm.GetUserInfo.CompanyId;
        vm.Currency = vm.GetUserInfo.Currency;  
        vm.GetitemDettail();
    },
    computed: {
        getTicketingDetailUrl() {
            var ticketData = encodeURIComponent(this.itemDetail.StrTicketNumber);
            return this.$router.resolve({ path: "/Ticketing/Manage/"+ ticketData +"" }).href;
        },
        getQuotationUrl() {
            return this.$router.resolve({ name: 'QuotationEdit', params: { id: this.itemDetail.ReferenceId } }).href;
        },
        getAssetRequisitionCommentUrl() {
            return this.$router.resolve({ name: 'AssetRequisitionDetail', params: { requisitionId: this.itemDetail.ReferenceId } }).href;
        },
        getNewAssetRequisitionUrl() {
            return this.$router.resolve({ name: 'AssetRequisitionListing', params: { requisitionId: this.itemDetail.ReferenceId } }).href;
        },
        getAssetRequisitionUrl() {
            return this.$router.resolve({ name: 'PendingRequisitionList', params: { reqId: this.itemDetail.ReferenceId } }).href;
        },
        getFeedbackUrl() {
            return this.$router.resolve({ name: 'UserFeedbackListing', params: { referenceId: this.itemDetail.ReferenceId } }).href;
        },
        getProjectOverviewUrl() {
            return this.$router.resolve({ name: 'ProjectOverview', params: { projectId: this.itemDetail.AddionalId, companyid: this.CompanyId, currency: this.Currency, tab: 'PROJECT_MESSAGES' } }).href;
        },
        getProjectOverviewOrRequestTimeUrl() {
            if (this.itemDetail.AssignFrom === 'RequestTime') {
                return this.$router.resolve({ name: 'RequestTimeList', params: {} }).href;
            } else {
                return this.$router.resolve({ name: 'ProjectOverview', params: { projectId: this.itemDetail.AddionalId, companyid: this.CompanyId, currency: this.Currency, tab: 'PROJECT_MESSAGES' } }).href;
            }
        },
        getTrackEntryFlagUrl() {
            return this.$router.resolve({ name: 'TrackEntryFlag', params: {} }).href;
        },
        getClientInvoiceUrl() {
            return this.$router.resolve({ name: 'CatchAll', params: { reqhFrom: 'clientbill', code: 'ClientBill' } }).href;
        },
        getAssetCatalogUrl() {
            return this.$router.resolve({ name: 'AssetCatalog', params: {} }).href;
        },
        getMyItemsUrl() {
            return this.$router.resolve({ name: 'MyItems', params: {} }).href;
        },
        getExpensesUrl() {
            return this.$router.resolve({ name: 'Expenses', params: {} }).href;
        }
    },
    methods: {
        GetitemDettail: function () {
            var vm = this;
            vm.isLoading = true;
            var url = `id=${vm.id}&type=${vm.type}`
            DataService.GetitemDetail(url).then(response => {
                vm.isLoading = false;
                console.log(response);
                vm.itemDetail = response.data;
                if (response.data == null) {
                    vm.$emit('close');
                }
            });
        },
        closePopup: function () {
            this.$emit('close');
        },
        formatTimeIn12Hour(date) {
            date = new Date(date);
            const hours24 = date.getHours();
            const minutes = date.getMinutes();
            const seconds = date.getSeconds();

            let hours12 = hours24 % 12;
            hours12 = hours12 ? hours12 : 12; // the hour '0' should be '12'
            const ampm = hours24 >= 12 ? 'PM' : 'AM';

            // Pad the minutes and seconds with leading zeros if necessary
            const minutesPadded = minutes < 10 ? '0' + minutes : minutes;
            const secondsPadded = seconds < 10 ? '0' + seconds : seconds;

            //return `${hours12}:${minutesPadded}:${secondsPadded} ${ampm}`;
            return `${hours12}:${minutesPadded} ${ampm}`;
        }
    }


}


</script>