</template>
<script>
//import GetQuickAddLayoutForm from "../HelpAndGuide/GetQuickAddLayoutForm.vue";
// import GetQuickAddLayoutForm from "../Wizard/GetQuickAddLayoutForm.vue";
import DataService from '../../services/DataService';
// import EN from '../../localization/en';
export default {
    // props: {
    //     LayoutListingData: {
    //         type: Array,
    //         required: true
    //     }
    // },
    components: {
        // GetQuickAddLayoutForm,
    },
    // i18n: {
    //     locale: "en",
    //     messages: {
    //         en: EN,
    //     },
    // },
    data() {
        return {
            //isCollapsed: false,

            isLoading: false,
            Quicklistdata: [],
            // moduledata:[],
            // manageform:false,
            //getAlllayoutData:[],
            // selectedModuleId: null,
            // getvalues: {},
            // IsManageForm: false,
            // submodulename:'',
            UserType: null,
        }
    },
    created() {
        debugger
        var vm = this;
        vm.UserType = vm.GetUserInfo.UserType;
        vm.getQuickAddData();
    },
    methods: {
        getForm(value) {
            var vm = this;
            // vm.getvalues = value;
            // vm.submodulename= value.sub_module_name;
            // vm.IsManageForm = true;  
            vm.$parent.openDynamicForm(value, value.sub_module_name);
        },
        getQuickAddData() {
            var vm = this;
            DataService.GetQuickAddDataListing().then((response) => {

                let data = response.data.data;

                // apply condition
                if (vm.UserType === 'PM') {
                    data = data.filter(item => item.sub_module_name !== 'User');
                }

                vm.Quicklistdata = data;                
            })
        },
        ClosePopup: function () {
            this.$parent.showWizard = false;
        },

    }

}
</script>
